def _stress(block, maps):
    gain, bias = maps[np.asarray(block['lab_id'])].T
    return (block['past_stress_cmd'] * gain[:, None] + bias[:, None], block['stress_hold_cmd'] * gain + bias)

def _plastic(hist, hold, dt, yield_stress):
    ov = np.maximum(np.abs(hold) - yield_stress, 0.0) ** 2 * np.sign(hold)
    work_hold = np.maximum(np.abs(hist) - yield_stress, 0.0) ** 2 @ dt * hold
    return (ov, work_hold)
